68cf7942920f","lesson_id":null,"japanese":"〜から","reading":"〜から","romaji":null,"indonesian":"karena (subjektif)","category":"助詞","note":null,"sort_order":2},"expectedDeckIds":["a5d64f4f-ded9-4c26-b2f5-c36f13439040"],"sourceExamples":[],"examples":[{"japanese":"きょうは さむいですから、うちに います。","reading":"きょうは さむいですから、うちに います。","highlight":"から","indonesian":"Karena hari ini dingin, saya berada di rumah."},{"japanese":"この かばんは やすいですから、かいます。","reading":"この かばんは やすいですから、かいます。","highlight":"から","indonesian":"Karena tas ini murah, saya akan membelinya."}]},{"vocabularyId":"ef839d58-9bda-4c40-9d35-cbab2fa4f058","chapter":20,"word":"〜と思う","lessonId":"a5d64f4f-ded9-4c26-b2f5-c36f13439040","expectedCore":{"module_id":"fb1923fe-e334-452b-bace-68cf7942920f","lesson_id":null,"japanese":"〜と思う","reading":"〜とおもう","romaji":null,"indonesian":"berpikir bahwa ~","category":"表現","note":"Quoting opinion","sort_order":38},"expectedDeckIds":["a5d64f4f-ded9-4c26-b2f5-c36f13439040"],"sourceExamples":[],"examples":[{"japanese":"この ほんは おもしろいと思います。","reading":"この ほんは おもしろいとおもいます。","highlight":"と思います","indonesian":"Menurut saya, buku ini menarik."},{"japanese":"あしたは あめだと思います。","reading":"あしたは あめだとおもいます。","highlight":"と思います","indonesian":"Saya pikir besok akan hujan."}]},{"vocabularyId":"dd488a8a-add0-4b11-8e97-d018cb35d5c1","chapter":20,"word":"だから","lessonId":"a5d64f4f-ded9-4c26-b2f5-c36f13439040","expectedCore":{"module_id":"fb1923fe-e334-452b-bace-68cf7942920f","lesson_id":null,"japanese":"だから","reading":"だから","romaji":null,"indonesian":"oleh karena itu","category":"接続詞","note":null,"sort_order":7},"expectedDeckIds":["a5d64f4f-ded9-4c26-b2f5-c36f13439040"],"sourceExamples":[],"examples":[{"japanese":"あしたは しけんです。だから、きょうは べんきょうします。","reading":"あしたは しけんです。だから、きょうは べんきょうします。","highlight":"だから","indonesian":"Besok ada ujian. Oleh karena itu, hari ini saya belajar."},{"japanese":"この かばんは やすいです。だから、これに します。","reading":"この かばんは やすいです。だから、これに します。","highlight":"だから","indonesian":"Tas ini murah. Oleh karena itu, s